"""Cuaderno del estudiante, 5.º básico Lenguaje y Comunicación, OA 16 (comentarios sobre lecturas: tema relevante fundamentado con ejemplos).

Los textos leídos son cuentos originales y breves, escritos para este cuaderno; cada ejercicio trae el texto que necesita.
Nota: los títulos genéricos de las clases del repositorio se reinterpretan según el OA oficial.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA16 = "LE05 OA 16"
E = ex

# Texto A (cuento original usado en varias clases)
A = ("«Nico vivía en un pueblo junto al mar y cuidaba el farol del muelle. Una noche de niebla espesa, su hermana le dijo que nadie lo notaría "
     "y que podía dormir. Nico igual encendió el farol. Horas después, tres barcos de pescadores volvieron guiados por la luz y llegaron a salvo. "
     "Al día siguiente nadie supo quién lo había hecho, pero Nico durmió contento.»")
# Texto B (cuento original)
B = ("«Lía prometió regar la planta de su vecina mientras ella viajaba. Un día llovió y pensó que no hacía falta ir. Pero recordó su promesa y fue de todos modos: "
     "el techo cubría la maceta y la tierra estaba seca. Lía la regó y la planta levantó sus hojas.»")


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


